    affiliateLinks: [{"label": "「改訂版 本当の自由を手に入れる お金の大学」（両＠リベ大学長）（楽天）", "label_en": "Okane no Daigaku (Money University), revised ed. — Japan's bestselling personal-finance guide (Japanese) (Rakuten)", "url": "https://hb.afl.rakuten.co.jp/hgc/g00q072n.kll75f32.g00q072n.kll76c1e/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fbook%2F18041936%2F&m=http%3A%2F%2Fm.rakuten.co.jp%2Fbook%2Fi%2F21432338%2F&rafcid=wsc_i_is_c18bf7b5-1871-492a-a3f5-afa07ce3dd0a"}, {"label": "「改訂版 本当の自由を手に入れる お金の大学」（両＠リベ大学長）（Amazon）", "label_en": "Okane no Daigaku (Money University), revised ed. — Japan's bestselling personal-finance guide (Japanese) (Amazon)", "url": "https://www.amazon.co.jp/dp/4023323780?tag=tokyodecoded-22"}],
